<?php
declare(strict_types=1); require __DIR__.'/lib/bootstrap.php'; require __DIR__.'/lib/layout.php'; require_permission('roles.read');
$roles=db()->query('SELECT * FROM cms_roles ORDER BY is_system DESC,name')->fetchAll();$permissions=db()->query('SELECT * FROM cms_permissions ORDER BY module_key,action')->fetchAll();$roleId=(int)($_GET['role']??($roles[0]['id']??0));$error=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{verify_csrf();$action=$_POST['action']??'';if($action==='role.create'){require_permission('roles.create');$key=slugify((string)$_POST['role_key']);$name=trim((string)$_POST['name']);$description=trim((string)$_POST['description']);if(!$name)throw new RuntimeException('Role name is required.');db()->prepare('INSERT INTO cms_roles(role_key,name,description,is_system) VALUES(?,?,?,0)')->execute([$key,$name,$description]);audit('roles.create','role',(int)db()->lastInsertId());flash('Role created.');}else{require_permission('roles.update');$id=(int)$_POST['role_id'];$roleCheck=db()->prepare('SELECT is_system FROM cms_roles WHERE id=?');$roleCheck->execute([$id]);$roleRow=$roleCheck->fetch();if(!$roleRow)throw new RuntimeException('Role not found.');if((int)$roleRow['is_system']===1)throw new RuntimeException('System roles are protected. Create a custom role for delegated access.');$selected=array_map('intval',$_POST['permissions']??[]);db()->prepare('DELETE FROM cms_role_permissions WHERE role_id=?')->execute([$id]);$ins=db()->prepare('INSERT INTO cms_role_permissions(role_id,permission_id) VALUES(?,?)');foreach($selected as $pid)$ins->execute([$id,$pid]);audit('roles.update','role',$id,['permissions'=>count($selected)]);flash('Permissions saved.');$roleId=$id;}redirect('roles.php?role='.$roleId);}catch(Throwable $e){$error=$e->getMessage();}}
$assigned=[];$st=db()->prepare('SELECT permission_id FROM cms_role_permissions WHERE role_id=?');$st->execute([$roleId]);$assigned=array_map('intval',array_column($st->fetchAll(),'permission_id'));$grouped=[];foreach($permissions as $p)$grouped[$p['module_key']][]=$p;page_start('Roles & Permissions','roles');
?><div class="page-head"><div><span class="eyebrow">SECURITY</span><h2>Roles & permissions</h2><p class="muted">Explicit CRUD permissions for every module. System roles remain protected.</p></div><button class="button primary" type="button" data-open-panel="roleCreatePanel">+ New role</button></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel modal-panel" id="roleCreatePanel" hidden><div class="panel-head"><h3>Create custom role</h3><button class="button ghost" type="button" data-close-panel="roleCreatePanel">Cancel</button></div><form method="post" data-ajax-form data-ajax-action="role.create" data-reload="true"><?=csrf_field()?><label>Role name<input name="name" placeholder="e.g. Content Manager" required></label><label>Role key<input name="role_key" placeholder="e.g. content-manager" required></label><label>Description<textarea name="description" placeholder="Describe what this role can manage." rows="3"></textarea></label><button class="button primary">Create role</button></form></section><section class="panel"><div class="role-tabs"><?php foreach($roles as $role):?><a class="<?=($role['id']==$roleId?'selected':'')?>" href="roles.php?role=<?=e($role['id'])?>"><?=e($role['name'])?></a><?php endforeach;?></div><?php $selectedRole=array_values(array_filter($roles,fn($r)=>(int)$r['id']===$roleId))[0]??null;if($selectedRole):?><form method="post" data-ajax-form data-ajax-action="roles.permissions" data-reload="true"><?=csrf_field()?><input type="hidden" name="role_id" value="<?=e($roleId)?>"><h3><?=e($selectedRole['name'])?></h3><p class="muted"><?=e($selectedRole['description'])?></p><?php if($selectedRole['is_system']): ?><div class="alert warning">System role permissions are protected. The Super Administrator role always retains all CRUD permissions.</div><?php endif; ?><div class="permission-grid"><?php foreach($grouped as $module=>$items):?><fieldset><legend><?=e(module_def($module)['label']??$module)?></legend><?php foreach($items as $p):?><label class="check"><input type="checkbox" name="permissions[]" value="<?=e($p['id'])?>" <?=in_array((int)$p['id'],$assigned,true)?'checked':''?> <?= $selectedRole['is_system']?'disabled':'' ?>> <?=e($p['action'])?></label><?php endforeach;?></fieldset><?php endforeach;?></div><?php if(!$selectedRole['is_system']&&can('roles.delete')):?><button class="button ghost" type="button" data-role-delete="<?=e($roleId)?>">Delete role</button><?php endif;?> <?php if(!$selectedRole['is_system']): ?><button class="button primary">Save permissions</button><?php endif; ?></form><?php endif;?></section><?php page_end();
